public class Main {
    static long power(long a, long b) {
        long ans = 1;
        if (b == 0)
            return 1;
        while (b > 0) {
            if (b % 2 != 0)
                ans = ans * a;
            a = a * a;
            b = b / 2;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        long i = 0, index = 0;
        while (n > 0) {
            int rem = (int) (n % 10);
            if (rem == 4)
                index += power(2, i);
            else
                index += power(2, i + 1);
            n = n / 10;
            i++;
        }
        System.out.println(index);
    }
}

